import math

def solve():
    coords = []
    with open('7dd30055-0198-452e-8c25-f73dbe27dcb8.pdb', 'r') as f:
        for line in f:
            if line.startswith('ATOM') or line.startswith('HETATM'):
                try:
                    x = float(line[30:38])
                    y = float(line[38:46])
                    z = float(line[46:54])
                    coords.append((x, y, z))
                    if len(coords) == 2:
                        break
                except ValueError:
                    continue

    if len(coords) < 2:
        print("Error: Less than two atoms found.")
        return

    dist = math.sqrt(sum((a - b) ** 2 for a, b in zip(coords[0], coords[1])))
    result = round(dist, 2)
    print(f"FINAL_ANSWER: {result}")

if __name__ == '__main__':
    solve()
